// System.Security.Cryptography.RIPEMD160Managed
uint F(uint x, uint y, uint z)
{
    return ((x ^ y) ^ z);
}

// System.Security.Cryptography.RIPEMD160Managed
uint G(uint x, uint y, uint z)
{
    return ((x & y) | ((-1 ^ x) & z));
}

// System.Security.Cryptography.RIPEMD160Managed
uint H(uint x, uint y, uint z)
{
    return ((x | (-1 ^ y)) ^ z);
}

// System.Security.Cryptography.RIPEMD160Managed
uint I(uint x, uint y, uint z)
{
    return ((x & z) | (y & (-1 ^ z)));
}

// System.Security.Cryptography.RIPEMD160Managed
uint J(uint x, uint y, uint z)
{
    return (x ^ (y | (-1 ^ z)));
}

